escenas.animacion:
const W=A.W, C=A.accent, RED='#FF4D5E';
A.bg('#050d1f','#0b1d3a');
const kT=A.k('telescopios',0.333), kP=A.k('poderosos',1.0), kNo=A.k('no',2.0);
const kEU=A.k('Estados',3.0), kEur=A.k('Europa…',4.333), kDes=A.k('desierto',5.667), kAt=A.k('Atacama',6.333);

// estrellas
A.particles(70, 7, (i, r) => {
  const x=r()*W, y=420+r()*700, s=1+r()*2.5, ph=r()*6;
  A.circle(x,y,s,{fill:'#fff',alpha:0.25+0.5*(0.5+0.5*Math.sin(t*2.5+ph))});
});

const gx=540, gy=790, R=300;
const gIn = A.p(kNo-0.15,0.7,'snapSettle');
const tStart = A.p(kNo-0.15,0.6,'glide');

// globo
if (gIn>0){
  A.with(()=>{
    A.circle(gx,gy,R,{fill:'#0f2a52',stroke:A.pal?A.pal.paleBlue:'#9cc4ff',lw:4});
    ctx.save(); ctx.beginPath(); ctx.arc(gx,gy,R,0,Math.PI*2); ctx.clip();
    for(let i=-2;i<=2;i++){ ctx.strokeStyle='rgba(156,196,255,0.18)'; ctx.lineWidth=2;
      ctx.beginPath(); ctx.ellipse(gx,gy,Math.abs(i)*R/2.6+2,R,0,0,Math.PI*2); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(gx-R,gy+i*R/3); ctx.lineTo(gx+R,gy+i*R/3); ctx.stroke(); }
    const conts=[
      [[-260,-200],[-150,-250],[-40,-230],[-20,-150],[-70,-90],[-90,-20],[-150,10],[-200,-60],[-250,-120]], // N. América
      [[-110,40],[-30,50],[20,110],[-10,170],[-50,230],[-75,280],[-90,220],[-100,130]], // S. América
      [[70,-230],[180,-250],[230,-190],[170,-140],[100,-150],[70,-190]], // Europa
      [[70,-110],[180,-120],[230,-30],[200,80],[150,190],[110,120],[60,10]] // África
    ];
    conts.forEach(c=>{
      const pts=c.map(([x,y])=>[gx+x,gy+y]);
      ctx.beginPath(); pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])); ctx.closePath();
      ctx.fillStyle='rgba(156,196,255,0.22)'; ctx.fill();
      ctx.strokeStyle='rgba(220,235,255,0.8)'; ctx.lineWidth=3; ctx.stroke();
      if (A.lib && A.lib.hatch) A.lib.hatch(ctx, pts, {angle:0.8, spacing:14, width:1.2, color:'rgba(220,235,255,0.25)'});
    });
    // franja de Atacama
    const at=A.p(kDes+0.1,0.8,'softLand');
    if(at>0) A.line([[gx-88,gy+70],[gx-80,gy+130],[gx-72,gy+185]],{stroke:C,lw:16,alpha:0.85,progress:at});
    ctx.restore();
  },{x:gx,y:gy,scale:A.lerp(0.6,1,gIn),alpha:gIn});
}

// trayectoria del marcador-telescopio
const P0=[540,830], PU=[gx-130,gy-130], PE=[gx+150,gy-185], PC=[gx-80,gy+140];
const m1=A.p(kEU-0.35,0.45,'glide'), m2=A.p(kEur-0.35,0.45,'glide'), m3=A.p(kDes-0.45,0.5,'whip');
let px=A.lerp(P0[0],PU[0],m1), py=A.lerp(P0[1],PU[1],m1);
px=A.lerp(px,PE[0],m2); py=A.lerp(py,PE[1],m2);
px=A.lerp(px,PC[0],m3); py=A.lerp(py,PC[1],m3);
const hop = Math.sin(Math.PI*m1)*60+Math.sin(Math.PI*m2)*60+Math.sin(Math.PI*m3)*140;
py -= hop;

// X rojas
function cross(x,y,st,lbl){
  if(t<st-0.4) return;
  const lp=A.p(st-0.4,0.4,'softLand');
  A.label(lbl,x,y-95,{size:34,bg:'rgba(10,20,40,0.85)',color:'#fff',alpha:lp*(t>st+0.2?0.55:1)});
  if(t<st+0.15) return;
  const s=A.pop(st+0.15,0.4);
  A.with(()=>{
    A.line([[x-38,y-38],[x+38,y+38]],{stroke:RED,lw:14});
    A.line([[x+38,y-38],[x-38,y+38]],{stroke:RED,lw:14});
  },{x,y,scale:s});
}
cross(PU[0],PU[1],kEU+0.33,'EE.UU.');
cross(PE[0],PE[1],kEur+0.33,'EUROPA');

// telescopio
function tel(x,y,s,a){
  ctx.save(); ctx.globalAlpha=a; ctx.translate(x,y); ctx.scale(s,s);
  ctx.strokeStyle='#fff'; ctx.lineWidth=6; ctx.lineCap='round';
  ctx.beginPath(); ctx.moveTo(-40,70); ctx.lineTo(0,0); ctx.lineTo(40,70); ctx.moveTo(0,0); ctx.lineTo(0,70); ctx.stroke();
  ctx.rotate(-0.75);
  ctx.fillStyle=C; ctx.beginPath(); ctx.moveTo(-70,-15); ctx.lineTo(80,-24); ctx.lineTo(80,24); ctx.lineTo(-70,15); ctx.closePath(); ctx.fill();
  ctx.strokeStyle='#0a1630'; ctx.lineWidth=4; ctx.stroke();
  ctx.fillStyle='#fff'; ctx.fillRect(80,-30,16,60);
  ctx.fillStyle='#0a1630'; ctx.fillRect(-20,-18,10,36);
  ctx.restore();
}
const tp=A.pop(kT,0.5);
const shakeAmt = (t>kEU+0.33&&t<kEU+0.6?8:0)+(t>kEur+0.33&&t<kEur+0.6?8:0)+(t>kDes&&t<kDes+0.35?14:0);
const ts=A.lerp(2.2,0.75,tStart)*tp;
// haz de luz
function beam(x,y,s,st,dur){
  const bp=A.p(st,0.5,'softLand'); if(bp<=0) return;
  const ex=x+Math.cos(-0.75)*96*s, ey=y+Math.sin(-0.75)*96*s;
  const L=(260+40*Math.sin(t*4))*bp*(s/1);
  const fade = dur? A.clamp(1-(t-st-dur)/0.3):1;
  ctx.save(); ctx.globalAlpha=0.5*fade;
  const g=ctx.createLinearGradient(ex,ey,ex+Math.cos(-0.75)*L,ey+Math.sin(-0.75)*L);
  g.addColorStop(0,C); g.addColorStop(1,'rgba(255,212,0,0)');
  ctx.fillStyle=g; ctx.translate(ex,ey); ctx.rotate(-0.75);
  ctx.beginPath(); ctx.moveTo(0,-26*s/2.2*2); ctx.lineTo(L,-90*s/2.2); ctx.lineTo(L,90*s/2.2); ctx.lineTo(0,26*s/2.2*2); ctx.closePath(); ctx.fill();
  ctx.restore();
  if(fade>0) A.circle(ex+Math.cos(-0.75)*L*0.9,ey+Math.sin(-0.75)*L*0.9,10*s/2.2+4,{fill:'#fff',glow:30,alpha:bp*fade});
}
if(tp>0){
  beam(px,py,ts,kP,kNo-kP-0.2);
  if(t>kDes+0.2) beam(px,py,ts*1.4,kDes+0.25,0);
  A.with(()=>tel(px,py,ts*(t>kDes?1+0.4*A.p(kDes,0.4,'snapSettle'):1),1),{shake:shakeAmt});
}

// aterrizaje en Chile
if(t>kDes){
  A.rings(PC[0],PC[1]+20,kDes,{count:3,speed:260,gap:0.18,maxR:220,color:C,lw:5});
  A.flash(kDes,0.25,0.35);
  const cp=A.p(kDes+0.15,0.4,'softLand');
  A.label('CHILE',PC[0]-150,PC[1]+40,{size:38,bg:C,color:'#0a1630',alpha:cp,scale:cp});
}

// zona secundaria
if(t>kP && t<kNo+0.3){
  const a=A.p(kP,0.4,'softLand')*A.clamp(1-(t-kNo)/0.3);
  A.text('LOS MÁS PODEROSOS',540,1480,{size:70,color:'#fff',weight:'900',align:'center',alpha:a});
}
if(t>kEU-0.3 && t<kDes){
  const a=A.p(kEU-0.3,0.4,'softLand')*A.clamp((kDes-t)/0.3);
  A.text('¿DÓNDE ESTÁN?',540,1480,{size:64,color:'rgba(255,255,255,0.75)',weight:'800',align:'center',alpha:a});
}
if(t>kAt-0.1){
  const s=A.pop(kAt-0.1,0.5);
  A.with(()=>{
    A.text('ATACAMA',540,1500,{size:150,color:C,weight:'900',align:'center',stroke:'#0a1630',strokeWidth:10});
    A.text('DESIERTO · CHILE',540,1610,{size:44,color:'#fff',weight:'700',align:'center',alpha:A.p(kAt+0.15,0.4)});
  },{x:540,y:1500,scale:s});
}

const W=A.W, H=A.H, ac=A.accent, BLUE='#6EC6FF';
A.bg('#0a1230','#170f22');
const kSeco=A.k('seco.',1.0), kVap=A.k('vapor',1.667), kAbs=A.k('absorbe',3.333), kDis=A.k('distorsiona',4.0), kLuz=A.k('luz',4.667), kAta=A.k('Atacama',6.333), kNo=A.k('no',7.0);
const CX=540, BAND0=610, BAND1=900;
// fondo de estrellas sutil
A.particles(40, 7, (i,r)=>{const x=r()*W, y=420+r()*560; const tw=0.4+0.4*Math.sin(t*2+i); A.circle(x,y,1.5+r()*2,{fill:'#ffffff',alpha:0.25*tw});});
// ---------- GOTA INTRO ----------
const pBurst=A.p(kVap,0.35,'crashOut');
if(pBurst<1){
  const sc=A.pop(0.15,0.5)*(1-pBurst);
  A.with(()=>{
    A.drop(CX,760,120,{fill:BLUE,stroke:'#ffffff'});
    A.line([[CX-150,640],[CX+150,880]],{stroke:ac,lw:16,progress:A.p(kSeco,0.35,'whip')});
  },{x:CX,y:760,scale:sc});
  if(t<kVap) A.text('SECO',CX,990,{size:70,weight:900,color:ac,alpha:A.p(kSeco,0.3),align:'center'});
}
// ---------- MOLECULAS ----------
const pSpread=A.p(kVap,0.9,'whip');
const pGone=A.p(kAta,0.8,'accelExit');
const pAbs=A.p(kAbs,0.5,'softLand');
const pDis=A.p(kDis,0.6,'glide');
const clear=1-pGone;
const rr=A.rand(42);
const mols=[];
for(let i=0;i<24;i++){mols.push({tx:110+rr()*860, ty:BAND0+20+rr()*(BAND1-BAND0-40), ph:rr()*6.28, s:0.8+rr()*0.5});}
if(t>=kVap){
  mols.forEach((m,i)=>{
    const survive=i<3;
    const g=survive?1:clear;
    if(g<=0.01) return;
    const x=A.lerp(CX,m.tx,pSpread)+Math.sin(t*1.7+m.ph)*14;
    const y=A.lerp(760,m.ty,pSpread)+Math.cos(t*1.3+m.ph)*10 - (survive?0:pGone*80);
    const near=Math.abs(x-CX)<170;
    const glow=pAbs*(near?1:0.3)*clear*(0.6+0.4*Math.sin(t*9+i));
    A.with(()=>{
      A.circle(x,y,20,{fill:BLUE,glow:glow>0.1?20:0});
      if(glow>0.05) A.circle(x,y,20,{fill:ac,alpha:glow*0.8});
      A.circle(x-22,y+14,10,{fill:'#ffffff'});
      A.circle(x+22,y+14,10,{fill:'#ffffff'});
    },{x,y,scale:m.s*A.clamp(pSpread*1.5)*(survive?1:(1-pGone*0.5)),alpha:g});
  });
  A.label('VAPOR DE AGUA',CX,BAND1+45,{size:34,bg:'rgba(110,198,255,0.2)',color:BLUE,alpha:A.p(kVap+0.4,0.4)*clear,scale:A.pop(kVap+0.4)});
}
// ---------- ESTRELLA Y TELESCOPIO ----------
const pStar=A.p(kVap+0.3,0.6,'snapSettle');
if(t>kVap){
  A.with(()=>{A.lib.glowDot(ctx,CX,470,22,{color:'#ffffff'}); A.sun(CX,470,26);},{x:CX,y:470,scale:pStar});
  // telescopio
  A.with(()=>{
    A.line([[CX,1050],[CX-60,1115]],{stroke:'#cfd8ff',lw:6});
    A.line([[CX,1050],[CX+60,1115]],{stroke:'#cfd8ff',lw:6});
    A.rect(CX-34,960,68,95,{r:10,fill:'#26305a',stroke:'#ffffff',lw:4});
    A.rect(CX-44,950,88,22,{r:6,fill:ac});
  },{x:CX,y:1050,scale:A.pop(kVap+0.5,0.5)});
}
// ---------- RAYO DE LUZ ----------
const pBeam=A.p(kAbs-0.25,0.7,'glide');
if(pBeam>0){
  const amp=pDis*34*clear;
  const yEnd=A.lerp(490,950,pBeam);
  const seg=(y0,y1,alpha,lw)=>{
    const pts=[];
    for(let y=y0;y<=y1;y+=8){
      const inside=A.clamp((y-BAND0)/80);
      const x=CX+Math.sin(y*0.045+t*10)*amp*inside+Math.sin(y*0.11-t*6)*amp*0.4*inside;
      pts.push([x,y]);
    }
    if(pts.length>1){
      ctx.save(); ctx.globalAlpha=alpha*0.35; ctx.strokeStyle=ac; ctx.lineWidth=lw*3; ctx.lineCap='round';
      ctx.beginPath(); pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])); ctx.stroke();
      ctx.globalAlpha=alpha; ctx.strokeStyle='#fff6e0'; ctx.lineWidth=lw; ctx.stroke(); ctx.restore();
    }
  };
  const dim=1-0.7*pAbs*clear;
  seg(490,Math.min(yEnd,BAND0),1,10);
  if(yEnd>BAND0) seg(BAND0,Math.min(yEnd,BAND1),A.lerp(1,dim,0.5),A.lerp(10,6,pAbs*clear));
  if(yEnd>BAND1) seg(BAND1,yEnd,dim,A.lerp(10,4,pAbs*clear));
}
// etiquetas de mecanismo
const lAlpha=clear;
if(t>kAbs) A.label('ABSORBE',250,560,{size:40,bg:ac,color:'#ffffff',scale:A.pop(kAbs,0.45),alpha:lAlpha});
if(t>kDis) A.label('DISTORSIONA',820,560,{size:40,bg:ac,color:'#ffffff',scale:A.pop(kDis,0.45),alpha:lAlpha});
// ---------- OCULAR ----------
const pEye=A.p(kLuz-0.4,0.5,'snapSettle');
if(pEye>0){
  const ey=1520, er=165;
  A.with(()=>{
    A.circle(CX,ey,er,{fill:'#050814',stroke:'#ffffff',lw:6});
    ctx.save(); ctx.beginPath(); ctx.arc(CX,ey,er-4,0,Math.PI*2); ctx.clip();
    const blur=pDis*28*clear;
    const bright=0.35+0.65*pGone;
    if(blur>1){
      for(let j=0;j<6;j++){
        const ox=Math.sin(t*11+j*1.7)*blur, oy=Math.cos(t*9+j*2.3)*blur;
        A.circle(CX+ox,ey+oy,26+blur*0.6,{fill:'#ffe6c8',alpha:0.12*bright+0.05});
      }
    }
    A.circle(CX,ey,A.lerp(18,12,pGone),{fill:'#ffffff',alpha:bright,glow:30*bright});
    if(pGone>0){
      A.line([[CX-80*pGone,ey],[CX+80*pGone,ey]],{stroke:'#ffffff',lw:3,alpha:pGone});
      A.line([[CX,ey-80*pGone],[CX,ey+80*pGone]],{stroke:'#ffffff',lw:3,alpha:pGone});
    }
    ctx.restore();
    A.line([[CX-er,ey],[CX-er+30,ey]],{stroke:ac,lw:4});
    A.line([[CX+er-30,ey],[CX+er,ey]],{stroke:ac,lw:4});
  },{x:CX,y:1520,scale:pEye});
  if(t<kAta) A.text('BORROSO',CX,1730,{size:44,weight:900,color:'#ff9d8a',align:'center',alpha:A.p(kDis+0.3,0.3)});
  else A.text('NÍTIDO',CX,1730,{size:52,weight:900,color:'#ffffff',align:'center',with:0,alpha:1});
}
// ---------- ATACAMA ----------
if(t>kAta){
  A.flash(kAta,0.3,0.25);
  A.rings(CX,470,kAta,{count:3,color:ac,maxR:260,lw:4});
  A.label('CASI SIN VAPOR',CX,780,{size:54,bg:ac,color:'#ffffff',scale:A.pop(kNo-0.2,0.5)});
}

const W=A.W, acc=A.accent;
A.bg('#06101f','#0b1d33',true);
const GY=1100;
const tAlt=A.k('altura',1.0), tAlma=A.k('ALMA',1.333), tCinco=A.k('cinco',2.333), tArr=A.k('arriba',3.333), tMenos=A.k('menos',4.0), tAtm=A.k('atmósfera',4.333);
// --- air particles (density decays with altitude)
const fadeAir=A.p(0,0.8,'softInOut');
A.particles(240,7,(i,r)=>{
  const u=r(); const h=-Math.log(1-u*0.97)*150; const y=GY-h; if(y<430) return;
  const x=((r()*1200+t*(18+r()*20))%1200)-60;
  const rr=2+r()*3;
  A.circle(x,y,rr,{fill:'#9fdcff',alpha:0.35*fadeAir*(0.5+0.5*Math.sin(t*2+i))});
});
// ground line
A.line([[40,GY],[1040,GY]],{stroke:'#cfe8ff',lw:4,progress:A.p(0,0.7,'glide')});
// --- mountain grows
const g=A.p(tAlt-0.1,0.9,'whip');
const base=[[300,1100],[470,880],[560,920],[700,640],[820,790],[900,770],[1050,1100]];
const pts=base.map(([x,y])=>[x,GY-(GY-y)*g]);
if(g>0.01){
  ctx.save();ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();
  ctx.fillStyle='#0a1628';ctx.fill();ctx.restore();
  A.lib.hatch(ctx,pts,{angle:-0.8,spacing:16,width:1.5,color:'rgba(77,208,225,0.35)'});
  A.lib.inkPath(ctx,pts,{width:4,color:'#e8f4ff',closed:false});
}
const peakY=GY-(GY-640)*g;
// --- ALMA dish
const sd=A.pop(tAlma,0.45);
if(sd>0.01){
  A.with(()=>{
    ctx.save();ctx.strokeStyle='#ffffff';ctx.lineWidth=5;ctx.fillStyle=acc;
    ctx.beginPath();ctx.moveTo(700,peakY);ctx.lineTo(700,peakY-40);ctx.stroke();
    ctx.beginPath();ctx.ellipse(700,peakY-55,38,16,-0.5,0,Math.PI);ctx.fill();ctx.stroke();
    ctx.beginPath();ctx.moveTo(700,peakY-55);ctx.lineTo(718,peakY-88);ctx.stroke();
    ctx.restore();
  },{x:700,y:peakY,scale:sd});
  A.label('ALMA',700,peakY+60,{size:38,bg:acc,color:'#06101f',scale:sd});
}
// sea-level person
A.person(220,GY,{scale:0.9,color:'#cfe8ff'});
// --- altitude axis + counter
const pc=A.p(tCinco-0.1,1.0,'glide');
if(pc>0){
  const ay=A.lerp(GY,640,pc);
  A.arrow(110,GY,110,ay,{color:acc,lw:6,head:22,progress:1});
  A.line([[110,640],[650,640]],{stroke:acc,lw:2,dash:[10,10],alpha:A.p(tCinco+0.8,0.4)*0.8});
  const sc=pc>=1?A.pop(tCinco+0.95,0.4):1;
  A.text(A.counter(0,5000,pc,0).replace(/\B(?=(\d{3})+(?!\d))/g,'.')+' m',140,ay+14,{size:58*sc,color:'#ffffff',weight:'800',align:'left',stroke:'#06101f',strokeWidth:8});
  if(pc>=1) A.rings(110,640,tCinco+0.95,{count:2,maxR:90,color:acc,lw:3});
}
// --- starlight rays
const st=A.pop(tArr-0.2,0.4);
if(st>0.01){
  const sx=470, sy=470;
  A.with(()=>{A.lib.glowDot(ctx,sx,sy,16,{color:'#fff6c8'});A.circle(sx,sy,8,{fill:'#ffffff'});},{x:sx,y:sy,scale:st});
  const pr=A.p(tArr,0.8,'glide');
  // to dish: straight, bright
  A.ray([[sx,sy],[700,peakY-60]],{color:'#fff6c8',lw:6,progress:pr});
  // to sea level: wobbly, dimming
  const wob=[]; const N=40;
  for(let i=0;i<=N;i++){const q=i/N; const x=A.lerp(sx,235,q), y=A.lerp(sy,GY-120,q); const a=q*q*14; wob.push([x+Math.sin(q*30+t*8)*a,y]);}
  A.line(wob,{stroke:'#fff6c8',lw:5,alpha:0.45,progress:pr});
  if(pr>0.95){
    const lp=A.p(tArr+0.75,0.4);
    A.text('distorsión',300,820,{size:34,color:'#ffb3c7',weight:'700',alpha:lp,align:'center'});
    A.text('nítida',800,560,{size:34,color:'#fff6c8',weight:'700',alpha:lp,align:'center'});
  }
}
// --- secondary: air above comparison
const bp=A.p(tMenos-0.15,0.5,'softLand');
if(bp>0){
  const x0=180, bw=720;
  A.text('AIRE ENCIMA',540,1385,{size:40,color:'#cfe8ff',weight:'800',alpha:bp});
  A.text('Nivel del mar',x0,1450,{size:34,color:'#ffffff',align:'left',alpha:bp});
  A.rect(x0,1470,bw*bp,60,{r:14,fill:'#5c7a99',alpha:bp});
  A.text('100%',x0+bw-20,1512,{size:34,color:'#06101f',weight:'800',align:'right',alpha:A.p(tMenos+0.3,0.3)});
  A.text('ALMA · 5.000 m',x0,1590,{size:34,color:acc,align:'left',alpha:bp});
  const sh=A.p(tAtm,0.6,'crashIn');
  const w=bw*bp*A.lerp(1,0.5,sh);
  A.with(()=>A.rect(x0,1610,w,60,{r:14,fill:acc,alpha:bp,glow:sh*20}),{x:x0,y:1640,shake:sh>0&&sh<1?6:0});
  if(sh>0.9){const s=A.pop(tAtm+0.55,0.4);A.label('½',x0+w+70,1640,{size:54,bg:'#ffffff',color:'#06101f',scale:s});}
  A.flash(tAtm+0.5,0.25,0.25);
}

const W=A.W, acc=A.accent;
A.bg('#050a1c','#0b1630',true);
