 const pc=A.p(tMas,0.7,'glide');
 const sc=A.lerp(1,0.6,pc);
 const cx=A.lerp(540,370,pc), cy=780;
 const Rf=300*sc;
 const R=Rf*A.lerp(0.12,1,pm);
 const shake=t>tG?14*(1-A.p(tG,0.45,'cruise')):0;
 A.with(()=>{
  A.circle(cx,cy,R+12*sc,{fill:'#0a2430',stroke:ac,lw:4,glow:20});
  const rv=A.p(tM+0.1,1.1,'glide');
  const s=16*(R/300);
  const kx=R/300;
  const sweep=(t-tM)*420-380;
  for(let q=-22;q<=22;q++)for(let r=-22;r<=22;r++){
   const lx=16*Math.sqrt(3)*(q+r/2), ly=16*1.5*r;
   const d=Math.hypot(lx,ly);
   if(d>286||d<34)continue;
   const a=A.clamp((rv*320-d)/40);
   if(a<=0)continue;
   const hx=cx+lx*kx, hy=cy+ly*kx;
   const sh=A.rand(q*31+r*7+99)();
   const gl=Math.exp(-Math.pow((lx+ly*0.5)-sweep,2)/(2*70*70));
   const L=40+sh*18+gl*35;
   ctx.beginPath();
   for(let k=0;k<6;k++){const an=Math.PI/6+k*Math.PI/3;const px=hx+Math.cos(an)*s*0.9,py=hy+Math.sin(an)*s*0.9;k?ctx.lineTo(px,py):ctx.moveTo(px,py);}
   ctx.closePath();
   ctx.globalAlpha=a;ctx.fillStyle=`hsl(187,70%,${L}%)`;ctx.fill();
   ctx.lineWidth=1;ctx.strokeStyle='rgba(4,18,28,0.8)';ctx.stroke();ctx.globalAlpha=1;
  }
  // cota de 39 m
  const pd=A.p(t39,0.6,'glide');
  if(pd>0){
   A.arrow(cx,cy,cx-Rf,cy,{progress:pd,color:'#ffffff',lw:5,head:18});
   A.arrow(cx,cy,cx+Rf,cy,{progress:pd,color:'#ffffff',lw:5,head:18});
   const val=A.counter(0,39,A.p(t39,1.1,'softLand'),0)+' m';
   A.label(val,cx,cy,{size:84*sc,bg:'#04121c',color:'#ffffff',scale:A.pop(t39)});
  }
  // persona a escala
  if(t>tMet&&pc<1){
   const pp=A.pop(tMet), al=1-pc;
   const h=2*Rf*1.8/39*pp, px=cx+Rf*0.72+30, py=cy+Rf*0.72+30;
   A.line([[px,py],[px,py-h*0.6]],{stroke:'#ffffff',lw:4,alpha:al});
   A.circle(px,py-h*0.6-h*0.15,h*0.15,{fill:'#ffffff',alpha:al});
   A.text('TÚ',px+38,py-h*0.4,{size:34,color:'#ffffff',weight:'800',align:'left',alpha:al});
  }
 },{x:cx,y:cy,shake});
 // comparación
 if(t>tMas){
  const others=[['VLT',8.2,'8 m',770,tMas+0.2],['KECK',10,'10 m',920,tMas+0.4]];
  for(const o of others){
   const sp=A.pop(o[4]);if(t<o[4])continue;
   const rr=Rf*(o[1]/39)*sp;
   A.circle(o[3],cy,rr,{fill:'#1b5563',stroke:'#ffffff',lw:3});
   A.text(o[0],o[3],cy-75,{size:34,color:'#ffffff',weight:'800',align:'center',alpha:A.clamp(sp)});
   A.text(o[2],o[3],cy+90,{size:40,color:ac,weight:'800',align:'center',alpha:A.clamp(sp)});
  }
 }
 if(t>tG){
  A.rings(cx,cy,tG,{count:3,speed:600,gap:0.12,maxR:520,color:ac,lw:4,alpha:0.6});
  A.flash(tG,0.25,0.25);
  A.label('EL MÁS GRANDE',540,1460,{size:78,bg:ac,color:'#04121c',scale:A.pop(tG)});
  A.text('DEL MUNDO',540,1580,{size:50,color:'#ffffff',weight:'800',align:'center',alpha:A.p(A.k('mundo',7.0),0.4,'softLand')});
 }
}

const W=A.W, ac=A.accent;
A.bg('#05101f','#0a1a33',true);
const kChile=A.k('Chile',1.0), kConc=A.k('concentra',1.333), kCuar=A.k('cuarenta',2.333), kCien=A.k('ciento',3.0);
const kCap=A.k('capacidad',4.0), kObs=A.k('observación',4.667), kPlan=A.k('planeta.',5.667);
const cx=540, cy=770, R=320, r0=165;
const TAU=Math.PI*2, a0=-Math.PI/2;
const FONT=A.FONT||'sans-serif';
const mw=(str,size,weight)=>{ctx.save();ctx.font=weight+' '+size+'px '+FONT;let w=ctx.measureText(str).width;ctx.restore();if(!w||isNaN(w))w=str.length*size*0.56;return w;};
const txt=(str,x,y,size,weight,color,align,alpha)=>{ctx.save();ctx.globalAlpha=alpha;ctx.font=weight+' '+size+'px '+FONT;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillStyle=color;ctx.fillText(str,x,y);ctx.restore();};
const wedgeP=A.p(kConc+0.2,(kCuar+0.25)-(kConc+0.2),'softInOut');
const aEnd=a0+TAU*0.4*wedgeP;
const hit=A.pop(kCuar,0.45);
const shake=t>kCuar&&t<kCuar+0.3?(1-(t-kCuar)/0.3)*10:0;
A.with(()=>{
  const ringP=A.p(0,0.9,'softLand');
  ctx.save();ctx.globalAlpha=0.9*ringP;
  ctx.beginPath();ctx.arc(cx,cy,R,0,TAU);ctx.arc(cx,cy,r0,0,TAU,true);
  ctx.fillStyle='#10233f';ctx.fill('evenodd');ctx.restore();
  const pts=[];for(let i=0;i<=40;i++){const a=i/40*TAU;pts.push([cx+Math.cos(a)*R,cy+Math.sin(a)*R]);}
  if(ringP>0.3) A.lib.hatch(ctx,pts,{angle:0.6,spacing:22,width:1,color:'rgba(140,180,255,0.10)'});
  A.circle(cx,cy,R,{stroke:'#cfe2ff',lw:4,alpha:ringP});
  A.circle(cx,cy,r0,{stroke:'#cfe2ff',lw:3,alpha:ringP*0.7});
  if(wedgeP>0){
    ctx.save();ctx.beginPath();ctx.arc(cx,cy,R,a0,aEnd);ctx.arc(cx,cy,r0,aEnd,a0,true);ctx.closePath();
    ctx.fillStyle=ac;ctx.globalAlpha=0.30+0.15*hit;ctx.shadowColor=ac;ctx.shadowBlur=30;ctx.fill();
    ctx.globalAlpha=1;ctx.lineWidth=6;ctx.strokeStyle=ac;ctx.stroke();ctx.restore();
  }
  const N=60;
  for(let i=0;i<N;i++){
    const rnd=A.rand(i*7+3);
    const sa=rnd()*TAU, sr=A.lerp(r0+20,R-20,rnd());
    const chile=i<24;
    const ta=chile? a0+TAU*0.4*(0.06+0.88*rnd()) : a0+TAU*(0.42+0.56*rnd());
    const tr=A.lerp(r0+25,R-25,rnd());
    const appear=A.p(0.1+i*0.012,0.4,'softLand');
    const mv=A.p(kConc+(i%12)*0.05,0.9,'glide');
    const a=A.lerp(sa,ta,mv), rr=A.lerp(sr,tr,mv);
    const x=cx+Math.cos(a)*rr, y=cy+Math.sin(a)*rr;
    const tw=0.6+0.4*Math.sin(t*5+i*1.7);
    const col=chile&&mv>0.5?ac:'#ffffff';
    const dim=(!chile&&t>kConc)?A.lerp(1,0.45,A.p(kConc,0.8)):1;
    A.circle(x,y,chile&&mv>0.5?8:6,{fill:col,alpha:appear*tw*dim,glow:chile&&mv>0.5?14:6});
  }
  const lp=A.pop(kChile,0.45);
  if(lp>0) A.text('CHILE',cx,cy-70,{size:52,color:ac,weight:'800',align:'center',alpha:Math.min(1,lp),scale:lp});
  if(t>kConc+0.2){
    const v=Math.round(40*wedgeP);
    A.with(()=>{
      A.text((t>kCuar?'≈':'')+v+'%',cx,cy+45,{size:120,color:'#ffffff',weight:'900',align:'center'});
    },{x:cx,y:cy+10,scale:1+0.25*(hit>0&&t<kCuar+0.45?Math.sin(Math.PI*(t-kCuar)/0.45):0)});
  }
},{x:cx,y:cy,shake:shake});
if(t>kCien) A.rings(cx,cy,kCien,{count:2,speed:500,gap:120,maxR:520,color:ac,lw:4,alpha:0.6});
if(t>kPlan) A.rings(cx,cy,kPlan,{count:2,speed:600,gap:140,maxR:560,color:'#cfe2ff',lw:3,alpha:0.4});
A.flash(kCuar,0.25,0.25);
// side labels outside the donut, with leader lines
const sideLabel=(str,ang,lx,ly,col,bord,start)=>{
  const lineP=A.p(start,0.3,'glide');
  if(lineP<=0) return;
  const px=cx+Math.cos(ang)*(R+6), py=cy+Math.sin(ang)*(R+6);
  const ty=ly-30;
  A.circle(px,py,7,{fill:bord,alpha:lineP,glow:10});
  A.line([[px,py],[lx,ty]],{stroke:bord,lw:3,alpha:0.9,progress:lineP});
  const bp=A.p(start+0.15,0.4,'softLand');
  if(bp<=0) return;
  const size=36, w=mw(str,size,'800');
  A.with(()=>{
    A.rect(lx-w/2-18,ly-28,w+36,56,{r:14,fill:'rgba(8,20,40,0.95)',stroke:bord,lw:3,alpha:bp});
    txt(str,lx,ly+1,size,'800',col,'center',bp);
  },{x:lx,y:ly,scale:0.85+0.15*bp});
};
sideLabel('CHILE 40%',a0+TAU*0.33,825,1108,ac,ac,kPlan-0.4);
sideLabel('RESTO DEL MUNDO 60%',a0+TAU*0.62,255,1108,'#cfe2ff','#8fb4ff',kPlan-0.1);
// domes row, growing from the center
const baseY=1560;
for(let i=0;i<10;i++){
  const d=A.pop(kCap+Math.abs(i-4.5)*0.07,0.4);
  if(d<=0) continue;
  const x=135+i*90;
  const on=i<4?A.p(kObs+i*0.08,0.3,'crashIn'):0;
  const col=on>0.5?ac:'#5a7299';
  A.with(()=>{
    ctx.save();ctx.beginPath();ctx.arc(x,baseY,32,Math.PI,0);ctx.lineTo(x+32,baseY+28);ctx.lineTo(x-32,baseY+28);ctx.closePath();
    ctx.fillStyle=col;ctx.globalAlpha=0.35+0.4*on;if(on>0.5){ctx.shadowColor=ac;ctx.shadowBlur=20;}ctx.fill();
    ctx.globalAlpha=1;ctx.lineWidth=3;ctx.strokeStyle=on>0.5?ac:'#cfe2ff';ctx.stroke();ctx.restore();
    A.rect(x-5,baseY-34,10,22,{fill:'#05101f'});
    if(on>0.5) A.line([[x,baseY-34],[x+18,baseY-90]],{stroke:ac,lw:3,alpha:0.8*on});
  },{x:x,y:baseY+28,scale:d});
}
const cp=A.p(kObs+0.3,0.5,'softLand');
if(cp>0){
  const s1='4 de cada 10', s2='observatorios', fs=44;
  const w1=mw(s1,fs,'800'), w2=mw(s2,fs,'600');
  const tot=w1+12+w2, sx=540-tot/2, yy=1680+(1-cp)*14;
  txt(s1,sx,yy,fs,'800',ac,'left',cp);
  txt(s2,sx+w1+12,yy,fs,'600','#ffffff','left',cp);
}

const W=A.W;
A.bg('#03061a','#0b1636',false);
const kEnt=A.k('entender',0.667), kChi=A.k('Chile',1.667), kMun=A.k('mundo.',2.667), kHas=A.k('¿Has',3.0), kCie=A.k('cielo',4.0), kNor=A.k('norte?',4.667);
const pSky=A.p(kHas,0.9,'softInOut');
// cielo que se oscurece/profundiza
ctx.save();
const g=ctx.createLinearGradient(0,420,0,1100);
g.addColorStop(0,'rgba(10,20,70,'+(0.5*pSky)+')');g.addColorStop(1,'rgba(0,0,0,0)');
ctx.fillStyle=g;ctx.fillRect(0,400,W,720);ctx.restore();
// Via Lactea
const pMW=A.p(kCie-0.1,1.0,'glide');
const x0=80,y0=1060,x1=1000,y1=430;
const ang=Math.atan2(y1-y0,x1-x0);
if(pMW>0){
  ctx.save();ctx.translate(540,745);ctx.rotate(ang);ctx.scale(1,0.22);
  const rg=ctx.createRadialGradient(0,0,0,0,0,560);
  rg.addColorStop(0,'rgba(255,236,170,'+(0.55*pMW)+')');
  rg.addColorStop(0.35,'rgba(170,150,255,'+(0.28*pMW)+')');
  rg.addColorStop(1,'rgba(40,40,120,0)');
  ctx.fillStyle=rg;ctx.beginPath();ctx.arc(0,0,560,0,Math.PI*2);ctx.fill();ctx.restore();
  const rb=A.rand(33);
  for(let i=0;i<220;i++){
    const u=rb(), off=(rb()-0.5)*(rb()*170), s=rb()*2.2+0.6;
    if(u>pMW) continue;
    const x=A.lerp(x0,x1,u)+Math.sin(ang)*off*-1, y=A.lerp(y0,y1,u)+Math.cos(ang)*off;
    if(y<420||y>1100) continue;
    A.circle(x,y,s,{fill:i%5==0?'#FFE9A0':'#ffffff',alpha:0.5+0.5*Math.sin(t*4+i)});
  }
}
// estrellas de fondo
const rs=A.rand(7);
for(let i=0;i<130;i++){
  const x=rs()*W,y=420+rs()*620,sz=rs()*2.4+0.8,ph=rs()*6.28,d=rs()*0.8;
  const tw=0.55+0.45*Math.sin(t*3+ph);
  const base=0.25+0.75*A.p(kCie+d*0.6,0.4,'softLand');
  A.circle(x,y,sz*(0.8+0.6*A.p(kCie+d*0.6,0.4)),{fill:'#fff',alpha:base*tw});
}
// haz del telescopio
const dx=540,dy=975;
const pBeam=A.p(kEnt,0.6,'softLand');
let a=-Math.PI/2+0.35*Math.sin(t*1.3);
const pAim=A.p(kNor-0.3,0.5,'glide');
const target=Math.atan2(745-dy,540+120-dx);
a=A.lerp(a,target,pAim);
if(pBeam>0){
  const L=520*pBeam;
  A.ray([[dx,dy-40],[dx+Math.cos(a)*L,dy-40+Math.sin(a)*L]],{color:A.accent,lw:8,progress:1});
}
// montañas
const mtn=[[0,1120],[0,1010],[160,940],[300,1000],[430,955],[540,935],[650,965],[800,900],[960,990],[1080,950],[1080,1120]];
A.lib.inkPath(ctx,mtn,{width:3,color:'#2b3a6a',closed:true,fill:'#02040d'});
A.lib.hatch(ctx,mtn,{angle:40,spacing:16,width:1.2,color:'rgba(110,140,220,0.22)'});
// cúpula
ctx.save();
ctx.fillStyle='#1a2550';ctx.strokeStyle='#e8eeff';ctx.lineWidth=4;
ctx.beginPath();ctx.rect(dx-62,dy-10,124,45);ctx.fill();ctx.stroke();
ctx.beginPath();ctx.arc(dx,dy-10,62,Math.PI,0);ctx.closePath();ctx.fill();ctx.stroke();
ctx.translate(dx,dy-10);ctx.rotate(a+Math.PI/2);
ctx.fillStyle=A.accent;ctx.globalAlpha=0.3+0.7*pBeam;ctx.fillRect(-9,-62,18,40);
ctx.restore();
// CHILE -> MUNDO
const exitG=A.p(kHas,0.45,'accelExit');
const sChi=A.pop(kChi)*(1-A.p(kMun-0.1,0.25,'accelExit'));
if(sChi>0.01) A.label('CHILE',540,640,{size:78,bg:A.accent,color:'#050a1f',scale:sChi});
const sG=A.pop(kMun,0.5)*(1-exitG);
if(sG>0.01){
  A.rings(540,640,kMun,{count:3,speed:420,gap:0.18,maxR:330,color:A.accent,lw:4,alpha:0.7});
  A.with(()=>{
    A.circle(540,640,120,{fill:'#0c1a44',stroke:A.accent,lw:5,glow:20});
    const rot=t*1.5;
    for(let m=0;m<4;m++){
      const w=Math.abs(Math.cos(rot+m*Math.PI/4))*120;
      ctx.save();ctx.strokeStyle=A.accent;ctx.globalAlpha=0.7;ctx.lineWidth=3;
      ctx.beginPath();ctx.ellipse(540,640,Math.max(w,1),120,0,0,Math.PI*2);ctx.stroke();ctx.restore();
    }
    A.line([[420,640],[660,640]],{stroke:A.accent,lw:3,alpha:0.7});
    A.text('MUNDO',540,812,{size:58,color:'#fff',weight:900,align:'center'});
  },{x:540,y:640,scale:sG});
}
// impacto final
A.flash(kNor,0.3,0.25);
const sN=A.pop(kNor-0.05,0.45);
if(sN>0.01){
  A.rings(540+120*0.8,745,kNor,{count:2,speed:300,gap:0.2,maxR:220,color:'#FFE9A0',lw:3,alpha:0.8});
  A.label('CIELO DEL NORTE',540,1420,{size:66,bg:A.accent,color:'#050a1f',scale:sN});
}
// "¿has visto?" pequeño ojo-pregunta
const sQ=A.pop(kHas+0.1,0.4)*(1-A.p(kNor-0.1,0.2,'accelExit'));
if(sQ>0.01) A.text('¿Lo has visto?',540,1440,{size:60,color:'#fff',weight:800,align:'center',alpha:sQ});
// botón seguir
A.follow(540,1620,0.15,0.85);
